class Factory:
 @classmethod
 async def create(cls,**kw):
  obj=await AsyncSandbox.create(**kw);created.append(obj); print(json.dumps({'created':obj.sandbox_id}),flush=True);return obj
async def authority(): pass
async def run(label,files,profile='python_unittest',**opts):
 config=E2BConfig(api_key=key,template_id=template,template_qualified=True,command_timeout_sec=opts.pop('command_timeout_sec',15),ttl_sec=90,**opts)
 result=await E2BRunner(config,sandbox_factory=Factory).run({k:v.encode() for k,v in files.items()},profile,operation_id='lifecycle-'+label,authority=authority)
 item={'label':label,**asdict(result)};results.append(item);print(json.dumps(item),flush=True)
