  obj=await AsyncSandbox.create(template=template,timeout=5,allow_internet_access=False,network={'deny_out':['0.0.0.0/0'],'allow_public_traffic':False},lifecycle={'on_timeout':'kill','auto_resume':False},api_key=key,request_timeout=15,retries=0)
